# Check if columns follow a pattern based on row
# Let's look at the first zero in each row that has a zero
first_zero_col = {}
last_zero_col = {}
for r, c in zeros:
    if r not in first_zero_col:
        first_zero_col[r] = c
    last_zero_col[r] = c

print("First and last zero column per row:")
for r in sorted(first_zero_col.keys()):
    print(f"  Row {r}: first zero at col {first_zero_col[r]}, last at col {last_zero_col[r]} (count: {last_zero_col[r] - first_zero_col[r] + 1})")

# Check the step between consecutive zeros in each row
print("\nZeros per row with steps:")
from collections import defaultdict
zeros_by_row = defaultdict(list)
for r, c in zeros:
    zeros_by_row[r].append(c)

for r in sorted(zeros_by_row.keys()):
    cols = sorted(zeros_by_row[r])
    if len(cols) >= 2:
        steps = set(cols[i+1] - cols[i] for i in range(len(cols)-1))
        print(f"  Row {r}: cols {cols[:5]}{'...' if len(cols) > 5 else ''}, step: {list(steps)[0]}")

